import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import * as vscode from "vscode";
import { applyPlanCriteria, buildGoalFile, currentGoalFileName, GOAL_PRESETS, parseCriteriaLink, slugify, tickCriteria } from "../../src/features/goal-catalog";
import { goalTemplate, parseGoal } from "../../src/features/goals";
import { matchLine, section } from "../../src/util/markdown";
import { ensureWorkspacePaths } from "../../src/features/workspace";

describe("goal catalog", () => {
	it("slugifies titles while keeping Korean", () => {
		expect(slugify("결제 모듈에 환불 API 추가!")).toBe("결제-모듈에-환불-api-추가");
		expect(slugify("   ")).toBe("goal");
		expect(slugify("a".repeat(60)).length).toBe(40);
	});

	it("builds a goal file from a preset", () => {
		const text = buildGoalFile({ title: "환불 API", description: "부분 환불 지원", criteria: GOAL_PRESETS[1].criteria, fileName: "x.md", stamp: "s" });
		const goal = parseGoal(text);
		expect(goal.title).toBe("환불 API");
		expect(goal.status).toBe("active");
		expect(goal.criteria).toHaveLength(4);
		expect(goal.criteria[0]).toContain("재현 절차와 원인 기록");
		expect(section(text, "목표")).toBe("부분 환불 지원");
		expect(matchLine(text, "목표 파일")).toBe(".vibe-code/goals/x.md");
		expect(currentGoalFileName(text)).toBe("x.md");
		expect(currentGoalFileName(goalTemplate("s"))).toBeUndefined();
	});

	it("ticks linked criteria by index", () => {
		const goal = goalTemplate("s");
		const ticked = tickCriteria(goal, [1, 3]);
		const lines = section(ticked, "완료 기준").split("\n");
		expect(lines[0].startsWith("- [x]")).toBe(true);
		expect(lines[1].startsWith("- [ ]")).toBe(true);
		expect(lines[2].startsWith("- [x]")).toBe(true);
		expect(tickCriteria("no sections", [1])).toBe("no sections");
		expect(parseCriteriaLink("연결 완료 기준: 1, 3 5\n")).toEqual([1, 3, 5]);
		expect(parseCriteriaLink("nothing")).toEqual([]);
	});
});

// `tickCriteria` writes `.vibe-code/goals/current.md` back through `applyPlanCriteria`, so it owes the
// same 줄바꿈 보존 contract as every other writer (`checkLine`, `setTaskDone`, `touchPlan`, `writeSection`).
describe("tickCriteria keeps the goal file's line endings", () => {
	const temps: string[] = [];

	function workspace(): string {
		const dir = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), "vibe-criteria-test-")));
		temps.push(dir);
		(vscode.workspace as { workspaceFolders: unknown }).workspaceFolders = [{ uri: { fsPath: dir } }];
		return dir;
	}

	afterEach(() => {
		(vscode.workspace as { workspaceFolders: unknown }).workspaceFolders = undefined;
		while (temps.length > 0) fs.rmSync(temps.pop() as string, { recursive: true, force: true });
	});

	it("returns a CRLF goal unchanged apart from the ticked boxes", () => {
		const crlf = goalTemplate("s").replace(/\n/g, "\r\n");
		const ticked = tickCriteria(crlf, [1, 3]);
		expect(ticked.split("\n").length).toBe(crlf.split("\n").length);
		expect(ticked.includes("\r\n")).toBe(true);
		expect(ticked.replace(/\r\n/g, "\n").includes("\n")).toBe(true);
		// Every line is byte-identical except the two that were ticked.
		expect(ticked.split("\r\n").filter((l, i) => l !== crlf.split("\r\n")[i])).toEqual(["- [x] 목표를 검증 가능한 기준으로 정리", "- [x] 최종 검증 통과"]);
	});

	it("writes current.md back with its CRLF endings through applyPlanCriteria", () => {
		const ws = workspace();
		const paths = ensureWorkspacePaths(true);
		expect(paths).not.toBeNull();
		const crlf = goalTemplate("s").replace(/\n/g, "\r\n");
		fs.writeFileSync((paths as NonNullable<typeof paths>).current, crlf, "utf8");

		const indexes = applyPlanCriteria(paths as NonNullable<typeof paths>, "연결 완료 기준: 1, 3\n");

		expect(indexes).toEqual([1, 3]);
		const after = fs.readFileSync(path.join(ws, ".vibe-code", "goals", "current.md"), "utf8");
		expect(after.match(/\r\n/g)?.length).toBe(crlf.match(/\r\n/g)?.length);
		expect(after.match(/(?<!\r)\n/g)).toBeNull();
		expect(section(after, "완료 기준").split("\n").map((l) => l.slice(0, 5))).toEqual(["- [x]", "- [ ]", "- [x]"]);
	});

	it("leaves an LF goal on LF", () => {
		const lf = goalTemplate("s");
		const ticked = tickCriteria(lf, [2]);
		expect(ticked.includes("\r")).toBe(false);
		expect(section(ticked, "완료 기준").split("\n").map((l) => l.slice(0, 5))).toEqual(["- [ ]", "- [x]", "- [ ]"]);
	});
});
