import { afterEach, beforeEach, describe, expect, it, type TestContext } from "vitest";
import { latestVsixVersion } from "../../src/features/update-check";

describe("latestVsixVersion", () => {
	let dir: string;

	beforeEach(() => {
		dir = fs.mkdtempSync(path.join(os.tmpdir(), "vibe-update-test-"));
	});

	afterEach(() => {
		fs.rmSync(dir, { recursive: true, force: true });
	});

	function symlink(context: TestContext, target: string, name: string, type: "file" | "dir"): void {
		try {
			fs.symlinkSync(target, path.join(dir, name), type);
		} catch (error) {
			const code = (error as NodeJS.ErrnoException).code;
			if (process.platform === "win32" && (code === "EPERM" || code === "EACCES")) {
				context.skip(`Windows symlink creation is not permitted (${code})`);
			}
			throw error;
		}
	}

	it("selects the actual package file even when a directory has a newer VSIX name", () => {
		fs.writeFileSync(path.join(dir, "vibe-code-1.10.1.vsix"), "package");
		fs.mkdirSync(path.join(dir, "vibe-code-99.0.0.vsix"));

		const version = latestVsixVersion(dir);
		expect(version).toBe("1.10.1");
		// Use the same install-input path construction as checkForUpdates.
		expect(fs.statSync(path.join(dir, `vibe-code-${version}.vsix`)).isFile()).toBe(true);
	});

	it("returns undefined when only VSIX-named directories exist", () => {
		fs.mkdirSync(path.join(dir, "vibe-code-99.0.0.vsix"));
		expect(latestVsixVersion(dir)).toBeUndefined();
	});

	it("returns undefined for an empty directory", () => {
		expect(latestVsixVersion(dir)).toBeUndefined();
	});

	it("orders package files numerically by version segment", () => {
		for (const version of ["1.2.0", "1.9.9", "1.10.0"]) {
			fs.writeFileSync(path.join(dir, `vibe-code-${version}.vsix`), "package");
		}
		for (const version of ["1.10.0", "1.9.9", "1.2.0"]) {
			expect(latestVsixVersion(dir)).toBe(version);
			fs.unlinkSync(path.join(dir, `vibe-code-${version}.vsix`));
		}
	});

	it("ignores unrelated names and other extensions", () => {
		for (const name of ["other-99.0.0.vsix", "vibe-code-99.0.0.zip", "vibe-code-99.0.0.vsix.bak", "notes.txt"]) {
			fs.writeFileSync(path.join(dir, name), "unrelated");
		}
		expect(latestVsixVersion(dir)).toBeUndefined();
		fs.writeFileSync(path.join(dir, "vibe-code-1.10.1.vsix"), "package");
		expect(latestVsixVersion(dir)).toBe("1.10.1");
	});

	it("allows a symbolic link to a package file", (context) => {
		const target = path.join(dir, "package.vsix");
		fs.writeFileSync(target, "package");
		symlink(context, target, "vibe-code-1.10.1.vsix", "file");

		const version = latestVsixVersion(dir);
		expect(version).toBe("1.10.1");
		expect(fs.statSync(path.join(dir, `vibe-code-${version}.vsix`)).isFile()).toBe(true);
	});

	it("excludes symbolic links to directories", (context) => {
		const target = path.join(dir, "packages");
		fs.mkdirSync(target);
		symlink(context, target, "vibe-code-99.0.0.vsix", "dir");
		expect(latestVsixVersion(dir)).toBeUndefined();
	});

	it("excludes broken symbolic links", (context) => {
		symlink(context, path.join(dir, "missing.vsix"), "vibe-code-99.0.0.vsix", "file");
		expect(latestVsixVersion(dir)).toBeUndefined();
	});

	it("keeps a valid candidate when another entry cannot be statted", (context) => {
		symlink(context, path.join(dir, "missing.vsix"), "vibe-code-0.0.0.vsix", "file");
		fs.writeFileSync(path.join(dir, "vibe-code-1.10.1.vsix"), "package");
		expect(latestVsixVersion(dir)).toBe("1.10.1");
	});

	it("propagates a directory read failure to the caller", () => {
		expect(() => latestVsixVersion(path.join(dir, "missing"))).toThrow();
	});
});
